@api.patch('/payments/{pid}')
async def update_payment(pid: str, payload: dict, _: dict = Depends(require_roles('owner','admin'))):
    p = await db.payments.find_one({'id': pid})
    if not p: raise HTTPException(404, 'Pago no encontrado')
    allowed = {'amount','method','concept','invoice_number','is_promise','promise_date','extension_days','notes'}
    upd = {k:v for k,v in (payload or {}).items() if k in allowed}
    upd['updated_at'] = now_iso()
    await db.payments.update_one({'id': pid}, {'$set': upd})
    p2 = await db.payments.find_one({'id': pid}, {'_id': 0})
    return p2
